#!/usr/bin/env node
// THE RUN-CARD LEGS' FACTS, GENERATED BY THE PRODUCER (lane wake-approve-card r11–r12 — 主开发's ruling «ONE producer contract»:
// vault-agent-own's src/vault-run.js `cardFactsOf` + the door's `whyAgain` are the ONLY author of a run card's facts; the legs'
// fixture is never hand-written). r12 (the r11 acceptance: the generator lived outside the repo and nothing went red when the
// producer drifted): it lives HERE, and test-wake-approve-card ⑳ re-derives the legs through `legsOf` from the tree it runs in
// whenever that tree carries the producer — a variant or a code that moved is RED there (the train), by name.
//
//   node scripts/make-vault-run-card-legs.mjs [--producer <dir>] [--commit <label>] [--write | --check]
//
// <dir> = the tree whose producer makes the facts (default: this repo). --write writes scripts/fixtures/vault-run-card-legs.json
// of THIS repo; --check exits 1 when its variants or codes differ from what the producer makes now.
// Every facts object a run-card leg injects: cardFactsOf over real plans (planOf → shapeOf), the door's `whyAgain` computed by the
// door's OWN whyAgainOf / exactPartsOf / cmdText (read out of src/server/vault-run-door.js — closures, not exports) and set as the
// door sets it (`if (whyAgain) facts.whyAgain = whyAgain;`); `codes` = VR.CARD_FACTS_CODES, the contract export. Deterministic:
// a fixed home, fake names and hosts only.
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { createRequire } from 'node:module';
import { fileURLToPath, pathToFileURL } from 'node:url';

const require = createRequire(import.meta.url);
const HERE = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const LEGS_FILE = 'scripts/fixtures/vault-run-card-legs.json';

/** Does `root` carry the producer? → `{ok, why}` (a tree without `cardFactsOf` — this lane's own, before the train — cannot make the legs). */
export function producerOf(root) {
  const vr = path.join(root, 'src/vault-run.js'), door = path.join(root, 'src/server/vault-run-door.js');
  if (!fs.existsSync(vr) || !fs.existsSync(door)) return { ok: false, why: 'no src/vault-run.js or src/server/vault-run-door.js' };
  const VR = require(vr);
  if (typeof VR.cardFactsOf !== 'function' || !VR.CARD_FACTS_CODES) return { ok: false, why: 'src/vault-run.js exports no cardFactsOf / CARD_FACTS_CODES' };
  if (!fs.readFileSync(door, 'utf8').includes('function whyAgainOf(prev, cur) {')) return { ok: false, why: 'the door has no whyAgainOf' };
  return { ok: true, VR };
}

/** The door's own whyAgain closures, read out of its source and evaluated as written. */
function doorOf(root) {
  const door = fs.readFileSync(path.join(root, 'src/server/vault-run-door.js'), 'utf8');
  const grab = (re, what) => { const m = door.match(re); if (!m) throw new Error(`the door's ${what} moved`); return m[0]; };
  const quoteSrc = grab(/^const quote = .*$/m, 'quote');
  const cmdTextSrc = grab(/^const cmdText = .*$/m, 'cmdText');
  const partsSrc = grab(/^\s*const exactPartsOf = .*$/m, 'exactPartsOf').trim();
  const whyStart = door.indexOf('function whyAgainOf(prev, cur) {');
  const whyEnd = door.indexOf('\n  }\n', whyStart);
  if (whyStart < 0 || whyEnd < 0) throw new Error("the door's whyAgainOf moved");
  if (!door.includes('if (whyAgain) facts.whyAgain = whyAgain;')) throw new Error("the door's whyAgain line moved");
  return new Function(`${quoteSrc}\n${cmdTextSrc}\n${partsSrc}\n${door.slice(whyStart, whyEnd + 4)}\nreturn { cmdText, exactPartsOf, whyAgainOf };`)();
}

/** → `{text, legs}`: the legs fixture `root`'s producer makes (`commit` = a provenance label only). Throws when `root` has none. */
export function legsOf(root = HERE, { commit = null } = {}) {
  const p = producerOf(root);
  if (!p.ok) throw new Error(`${root}: ${p.why}`);
  const VR = p.VR, DOOR = doorOf(root);
  const sha = (f) => crypto.createHash('sha256').update(fs.readFileSync(path.join(root, f))).digest('hex').slice(0, 12);
  const HOME = '/home/user', CWD = `${HOME}/workspace/ops`;
  const planOf = (req) => { const x = VR.planOf(req); if (!x.ok) throw new Error(`a plan did not parse: ${x.code} ${x.why || ''} ${JSON.stringify(req.argv).slice(0, 80)}`); return x; };
  // THE DOOR'S ROAD: facts = cardFactsOf(spec, shape, place, names{cmd: cmdText(argv)}); then the whyAgain line, as written
  const factsOf = (req, names, { cwd = CWD, prev = null } = {}) => {
    const spec = planOf(req);
    const facts = VR.cardFactsOf(spec, VR.shapeOf(spec), cwd, { home: HOME, cmd: DOOR.cmdText(spec.argv), ...names });
    const whyAgain = prev ? DOOR.whyAgainOf(DOOR.exactPartsOf(planOf(prev.req), prev.cwd || cwd), DOOR.exactPartsOf(spec, cwd)) : null;
    if (whyAgain) facts.whyAgain = whyAgain;
    return facts;
  };
  const UNIFI = ['./office-net/unifi-api.sh', 'PUT', '/proxy/network/api/s/default/rest/networkconf/5f9c3a6e8b2d4c0012a7e1f4', '/tmp/unifi-work/wan2-primary.json'];
  const UENV = [['UNIFI_USER', 'vault://secrets/unifi-account/username'], ['UNIFI_PASS', 'vault://secrets/unifi-account/password']];
  const UNAMES = { 'secrets:unifi-account#username': 'UniFi 账号 · 用户名', 'secrets:unifi-account#password': 'UniFi 账号 · 密码' };
  const UINFO = [{ id: 'secrets:unifi-account#username', own: true, prov: 'stored', open: true }, { id: 'secrets:unifi-account#password', own: true, prov: 'stored', open: true }];
  const UAWAY = [{ id: 'secrets:unifi-account#username', ref: 'vault://secrets/unifi-account/username', forHost: null, unknown: true, keep: false }, { id: 'secrets:unifi-account#password', ref: 'vault://secrets/unifi-account/password', forHost: null, unknown: true, keep: false }];
  const unifi = (argv = UNIFI, env = UENV, resolved = `${CWD}/office-net/unifi-api.sh`) => ({ argv, env, resolved, programWritable: true });
  const WHO = 'ops watch';
  const uNames = { who: WHO, entries: UNAMES, refsInfo: UINFO, away: UAWAY };
  // a command of EXACTLY n characters as the door quotes it (cmdText): UNIFI + --note + one quoted arg of a' pairs (5 units each) and b's
  const longArgv = (n) => {
    const head = DOOR.cmdText([...UNIFI, '--note']).length + 1 + 2;
    const k = Math.floor((n - head) / 5), r = n - head - 5 * k;
    const argv = [...UNIFI, '--note', "a'".repeat(k) + 'b'.repeat(r)];
    if (DOOR.cmdText(argv).length !== n) throw new Error(`longArgv(${n}) = ${DOOR.cmdText(argv).length}`);
    return argv;
  };
  const variants = [];
  const add = (name, facts, why) => variants.push({ name, why, facts });
  // the r7 legs: the owner's unifi run (hosts unknown — 发往 decides), a known tool naming a host (Always offered), a config read
  add('ops', factsOf(unifi(), uNames), 'r7 ⑧: the owner\'s run — an agent-writable program, two env secrets of ONE entry, no host it declares');
  add('known-always', factsOf({ argv: ['psql', '-h', 'db.example.com', '-U', 'svc', '-c', 'select 1'], env: [['PGPASSWORD', 'vault://secrets/prod-db/password']], resolved: '/usr/bin/psql', programWritable: false },
    { who: WHO, entries: { 'secrets:prod-db#password': '生产数据库 · 密码' }, refsInfo: [{ id: 'secrets:prod-db#password', own: false, open: true }], away: [], notOwn: false }), 'r7 ⑧: «Always» offered — no hint, nothing marked');
  add('config-reads', factsOf({ argv: ['curl', '-sS', '-K', '$VAULT_FILE{B}'], file: [['B', '@b.cfg']], templates: { 'b.cfg': 'config ./more.cfg\nheader = "X-Auth: $VAULT{secrets/api-token/token}"\n' }, resolved: '/usr/bin/curl', programWritable: false },
    { who: WHO, entries: { 'secrets:api-token#token': 'API 令牌' }, refsInfo: [{ id: 'secrets:api-token#token', own: false, open: true }], away: [] }), 'r7 ⑧: «Always» withheld by a config read — the hint names it and its directive');
  // the stress shape: a ~300-character command, 4 entries (one named in 40+ CJK characters), 3 hosts, the program the deciding row
  const SN = ['运维控制器本地管理员账号用于读取广域网状态和切换主线路的那一个账号条目名字很长很长很长', 'B', 'C', 'D'];
  const sEnv = SN.map((_, k) => [`STRESS_${k}`, `vault://secrets/stress-${k}/secret`]);
  add('stress', factsOf({ argv: ['./bin/curl', '-s', 'https://a.example.com:443/v1/' + 'a1b2c3d4e5f6'.repeat(8), 'https://b.example.com/v1/' + 'a1b2c3d4e5f6'.repeat(8), 'https://10.0.0.7:8443/v1/items'], env: sEnv, resolved: `${CWD}/bin/curl`, programWritable: true },
    { who: WHO, entries: Object.fromEntries(SN.map((n, k) => [`secrets:stress-${k}#secret`, `${n} · 密码`])), refsInfo: SN.map((_, k) => ({ id: `secrets:stress-${k}#secret`, own: false, open: true })), away: [] }), 'r7 ⑧: the stress shape — wrapped inside the card, «程序» first');
  // r9 ⑨: the clip notes — a whole fold (2 973) and one the store cuts at 4 096 (5 037)
  add('clip-2973', factsOf(unifi(longArgv(2973)), uNames), 'r9 ⑨: a 2 973-character command — cmd its first 2 000, cmdCut, the WHOLE in cmdFull');
  add('clip-5037', factsOf(unifi(longArgv(5037)), uNames), 'r9 ⑨: a 5 037-character command — the store keeps 4 096 of the fold and names cmdFull in `cut`');
  // r11: THE FOLDS (r25 clipFold) + whyAgain — a 2 100-character plain env value, a secret named in 2 100 characters; the rerun
  // differs from the command let through late in its ARGUMENT ORDER (the door's whyAgainOf over the two exact parts)
  const NOTE = ('wan2-primary failover window ' + '0123456789abcdef'.repeat(140)).slice(0, 2100);
  const foldEnv = [...UENV, ['RUN_NOTE', NOTE]];
  const LONGNAME = ('UniFi 账号 · 用户名 ' + '（运维控制器本地管理员）'.repeat(200)).slice(0, 2100);
  add('fold', factsOf(unifi([UNIFI[0], UNIFI[2], UNIFI[1], UNIFI[3]], foldEnv), { ...uNames, entries: { ...UNAMES, 'secrets:unifi-account#username': LONGNAME } }, { prev: { req: unifi(UNIFI, foldEnv) } }),
    'r11: a 2 100-character env value (valueCut + valueFull), a 2 100-character secret name (nameCut + nameFull), whyAgain arg-order');
  // r11: whyAgain — each dimension the door can name, through its own whyAgainOf (the same run but the ONE difference)
  const tagEnv = (v) => [...UENV, ['RUN_TAG', v]];
  add('again-env', factsOf(unifi(UNIFI, tagEnv('r7-2')), uNames, { prev: { req: unifi(UNIFI, tagEnv('r7-1')) } }), 'r11: whyAgain env (RUN_TAG changed)');
  add('again-folder', factsOf(unifi(), uNames, { cwd: `${CWD}/sub`, prev: { req: unifi(), cwd: CWD } }), 'r11: whyAgain folder');
  add('again-secret-set', factsOf(unifi(UNIFI, UENV.slice(0, 1)), uNames, { prev: { req: unifi() } }), 'r11: whyAgain secret-set');
  add('again-arg-space', factsOf(unifi([...UNIFI.slice(0, 3), '/tmp/unifi-work/wan2  primary.json']), uNames, { prev: { req: unifi([...UNIFI.slice(0, 3), '/tmp/unifi-work/wan2 primary.json']) } }), 'r11: whyAgain arg-space');
  add('again-args', factsOf(unifi([...UNIFI.slice(0, 3), '/tmp/unifi-work/wan1-primary.json']), uNames, { prev: { req: unifi() } }), 'r11: whyAgain args');
  // a config directive past the bound (always.directiveCut + directiveFull)
  const DIR = 'config ./' + 'd'.repeat(2100) + '.cfg';
  add('directive-long', factsOf({ argv: ['curl', '-sS', '-K', '$VAULT_FILE{B}'], file: [['B', '@b.cfg']], templates: { 'b.cfg': `${DIR}\nheader = "X-Auth: $VAULT{secrets/api-token/token}"\n` }, resolved: '/usr/bin/curl', programWritable: false },
    { who: WHO, entries: { 'secrets:api-token#token': 'API 令牌' }, refsInfo: [{ id: 'secrets:api-token#token', own: false, open: true }], away: [] }), 'r11: a config directive past the bound (directiveCut + directiveFull)');
  // r12 (the r11 acceptance, probe-producer-unmarked-clips.cjs): a run in a 2 207-character folder, its program at the folder's
  // TAIL («…/evil-tail/run.sh», 2 224 characters) — the producer folds `folder` and `tool.path` like an env value (folderCut +
  // folderFull, tool.pathCut + pathFull); and a value minted for no host whose reference is 2 100 characters (reason.away[].ref)
  const DEEP = `${CWD}/` + Array.from({ length: 120 }, (_, k) => `nested-level-${String(k).padStart(3, '0')}-dir`).join('/');
  const LONGCWD = DEEP.slice(0, 2207 - '/evil-tail'.length).replace(/\/$/, 'x') + '/evil-tail';
  if (LONGCWD.length !== 2207) throw new Error(`LONGCWD ${LONGCWD.length}`);
  add('folder-long', factsOf(unifi(['./run.sh', 'PUT'], UENV, `${LONGCWD}/run.sh`), uNames, { cwd: LONGCWD }),
    `r12: a ${LONGCWD.length}-character working folder and its ${LONGCWD.length + '/run.sh'.length}-character program at the tail — folderCut + folderFull, tool.pathCut + pathFull`);
  const LONGREF = ('vault://secrets/unifi-account/' + 'p'.repeat(2100)).slice(0, 2100);
  add('away-ref-long', factsOf(unifi(), { ...uNames, away: [{ ...UAWAY[0], ref: LONGREF }] }), 'r12: a reason line whose reference is 2 100 characters — reason.away[].refCut + refFull');
  const legs = {
    v: 2,
    _: 'GENERATED — never hand-edit: node scripts/make-vault-run-card-legs.mjs --write (test-wake-approve-card ⑳ re-derives it from the producer wherever the tree carries one). Lane wake-approve-card r11–r12: every facts object a run-card leg injects (test-wake-approve-card, test-wake-approve-card-chrome), made by the PRODUCER (lane vault-agent-own src/vault-run.js cardFactsOf over real plans; the door\'s own whyAgainOf / exactPartsOf / cmdText for `whyAgain`, set as the door sets it). `codes` = VR.CARD_FACTS_CODES, the contract export.',
    producer: { commit, 'src/vault-run.js': sha('src/vault-run.js'), 'src/server/vault-run-door.js': sha('src/server/vault-run-door.js') },
    codes: VR.CARD_FACTS_CODES,
    variants,
  };
  return { legs, text: JSON.stringify(legs, null, 2) + '\n' };
}

/** What a re-derivation compares: the codes and every variant (the provenance — commit, file hashes — is a label, not a fact). */
export const factsPart = (legs) => JSON.stringify({ codes: legs.codes, variants: legs.variants });

if (process.argv[1] && pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url) {
  const arg = (k) => (process.argv.includes(k) ? process.argv[process.argv.indexOf(k) + 1] : null);
  const root = path.resolve(arg('--producer') || HERE);
  const p = producerOf(root);
  if (!p.ok) { console.error(`${root}: ${p.why} — this tree cannot make the legs (run it with --producer <a tree that carries vault-agent-own's producer>)`); process.exit(2); }
  const { legs, text } = legsOf(root, { commit: arg('--commit') });
  const file = path.join(HERE, LEGS_FILE);
  const before = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  const same = before != null && factsPart(JSON.parse(before)) === factsPart(legs);
  console.log(`${LEGS_FILE}: ${legs.variants.length} variants (${legs.variants.map((v) => v.name).join(', ')}), ${text.length} B — ${before == null ? 'NEW' : before === text ? 'IDENTICAL' : same ? 'the same facts (only the provenance differs)' : 'DIFFERS'}`);
  for (const v of legs.variants) {
    const f = v.facts, cuts = [];
    const walk = (x, at) => { if (x && typeof x === 'object') for (const [k, y] of Object.entries(x)) { if (/Cut$/.test(k) && y === true) cuts.push(`${at}${k}`); walk(y, `${at}${Array.isArray(x) ? `[${k}]` : k}.`); } };
    walk(f, '');
    console.log(`   ${v.name.padEnd(17)} who ${JSON.stringify(f.who)} · cmd ${f.cmd.length}${f.cmdCut ? ` (+cmdFull ${f.cmdFull.map((c) => c.length).join('+')})` : ''} · folder ${f.folder.length}${f.whyAgain ? ' · whyAgain ' + JSON.stringify(f.whyAgain) : ''}${cuts.length ? ' · cut ' + cuts.join(' ') : ''} · ${JSON.stringify(f).length} B`);
  }
  if (process.argv.includes('--write')) { fs.writeFileSync(file, text); console.log(`written: ${file}`); }
  if (process.argv.includes('--check') && !same) process.exit(1);
}
